{"record_type":"obligation_result","obligation_index":1,"status":"items","reason_code":null,"items":[{"text":"咱们这会儿讲锂电，先不提标箔，一次把锂电的几个问题提完，等会儿再统一说标箔，行吗？","semantic_type":"unknown","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"unknown","behavior_status":null,"temporal_frame":"unknown","evidence_selector":"slot"}]}
